        "texto": "Acción: Estimulante reproductivo.\nIndicaciones: Está indicado para el tratamiento de trastornos reproductivos relacionado con las\ndeficiencias de los elementos de la fórmula. Coadyuvante en el tratamiento de atrofia de los\novarios y los testículos, anestro, ovarios estáticos, retención de la placenta, reabsorción fetal.\nFavorece la reaparición del celo, estimula la función reproductiva y la maduración folicular,\nmejorando la tasa de concepción. En los machos, ayuda a prevenir el descenso de la libido, la baja\ncalidad del semen y los trastornos de la espermatogénesis. Apoyo en problemas de retardo del\ncrecimiento y baja respuesta inmunológica en los animales.\nFórmula: Fósforo, Selenio y Vitamina E.\nDosificación: Vía intramuscular. Bovinos, Equinos, Porcinos y Ovinos: Administrar 5 ml por cada\n100 kilos de peso vivo, vía intramuscular profunda. Administrar cada 24 horas hasta 3 días consecutivos o según criterio del médico veterinario. Presentación: Viales por 50 ml, 100 ml y 250 ml.\nSolución inyectable estéril.\nUso: Bovinos, Equinos, Ovinos y Porcinos.",
