        "texto": "Acción: Antiséptico para uso ótico, tópico y odontológico.\nIndicaciones: Desinfección de heridas. Control de infecciones óticas. Desinfección del campo\nquirúrgico, prevención y/o tratamiento de contaminación bacteriana Grampositiva y/o Gramnegativa y/o fúngica de la piel. Control de tiñas producidas por Tricophytum (verrucosum, equinum\ny nanum), desinfección de ubres post-ordeñe, tratamiento del Dermatophylus congolensis, control\nde Metritis Contagiosa Equina, desinfección de instalaciones empleadas en la industria avícola,\ntratamiento de infecciones causadas por Staphylococcus hyicus.\nFórmula: Digluconato de Clorhexidina al 20% 2,50 g; agentes de formulación c.s.p. 100 ml.\nDosificación:\n• Otitis: Preventivo: 1 a 3 ml/24hs. Curativo: 3 a 5 ml/24 hs.\n• Desinfección de heridas: Aplicar el producto de forma tópica de acuerdo con el tamaño de la\nherida.\n• Uso ambiental: El producto puede utilizarse a su concentración original, o diluirse hasta una\nproporción de 1 parte del producto y 30 partes de agua.\n• Uso odontológico: Irrigar la cavidad bucal mediante aspersión o aplicando el producto con gasa\nsobre la superficie dental.\nPresentaciones: Frasco gotero, contenido 50 ml de producto. Botella con válvula atomizadora\ncontenido 1 litro de producto. Bidón de 5 litros de producto.\nUso: Bovinos, Equinos, Ovinos, Porcinos, Caninos y Felinos.",
