        "texto": "Acción: Antiinflamatorio, analgésico y antipirético.\nIndicaciones: Bovinos: Tratamiento de la inflamación aguda asociada con enfermedades del\ntracto respiratorio, mastitis aguda, coadyuvante en el tratamiento de babesiosis y anaplasmosis.\nPorcinos: Ayuda en el tratamiento del síndrome MMA (Metritis-Mastitis-Agalaxia). En todos\naquellos casos en los que esté contraindicada una terapia antiinflamatoria con corticoides.\nEquinos: en el tratamiento de dolores viscerales asociados al cólico. Tratamiento de inflamaciones\ny dolores asociados a alteraciones músculo-esqueléticas. Lesiones de carrera o como posquirúrgico. Caninos: se utiliza en procesos de artritis y lesiones de disco medular, aunque no se recomienda más de una aplicación.\nFórmula: Flunixin Meglumine: 50 mg, Excipiente c.s.p. : 1 ml.\nDosificación: Bovinos: Administrar por vía intravenosa lenta o intramuscular 2 mL por cada 45 Kg\nde peso vivo, repetir cada 24 horas, máximo hasta 3 días consecutivos. Porcinos: Administrar por\nvía intramuscular 2 mL por cada 45 Kg de peso vivo, por día, en la musculatura del cuello, con un\nmáximo de 10 mL por sitio. Máximo hasta 3 días. Equinos: Administrar por vía intravenosa o\nintramuscular 1 mL por cada 45 Kg de peso vivo, repetir cada 24 horas, máximo hasta 3 días\nconsecutivos. Caninos: Administrar por vía intravenosa 1 mL por cada 45 Kg de peso vivo, repetir\ncada 24 horas, máximo hasta 3 días consecutivos.\nPresentaciones: Viales por 20 ml y 50 ml. Solución inyectable estéril.\nUso: Bovinos, Equinos, Porcinos y Caninos.",
