        "texto": "Acción: Suspensión Antibiótica intramamaria de amplio espectro.\nIndicaciones: el secado de la vaca ayuda a prevenir la mastitis después del parto, evitando graves\nproblemas en la producción y pérdidas económicas. Debe ser aplicado después del último ordeño\nde lactación, previa desinfección y escurrimiento de los pezones. Introducir el contenido de la\njeringa en el cuarto afectado. Hacer masaje sobre la ubre para una mejor difusión del medicamento.\nEn caso de mastitis clínica, aplicar en el cuarto afectado con la frecuencia que indique el médico\nveterinario.\nFórmula: Cloxacilina Benzatínica, Ampicilina Trihidrato.\nDosificación: Administrar una jeringa (350 mg de Ampicilina y 700 mg de Cloxacilina benzatinica),\nen el cuarto afectado. Al inicio del periodo de secado. Si es necesario, repetir el tratamiento a las 24\nhoras.\nPresentaciones: Cubeta conteniendo 60 jeringuillas o cánulas de 10 ml.\nUso: Bovinos.",
