        "pagina": 16,
        "texto": "Acción: Shampoo antiséptico externo.\nIndicaciones: Desinfección de heridas. Control de infecciones por Tricophytum spp, desinfección\ndel campo quirúrgico. Prevención y/ o tratamiento de contaminación bacteriana Grampositiva y/o\nGramnegativa y/o fúngica de la piel. Control de tiñas producidas por Tricophytum (verrucosum,\nequinum y nanum), desinfección de ubres post-ordeñe, tratamiento del Dermatophylus congolensis, control de Metritis Contagiosa Equina, desinfección de instalaciones empleadas en la industria\navícola, tratamiento de infecciones causadas por Staphilococus hyicus.\nFórmula: Digluconato de Clorhexidina al 20% 2,50 g; agentes de formulación c.s.p. 100 ml.\nDosificación:\n• Desinfección de heridas: Aplicar el producto de forma tópica de acuerdo con el tamaño de la\nherida.\n• Uso ambiental: Aplicar el producto a su concentración original sobre las superficies inertes,\ncampo quirúrgico o manos a desinfectar. Dejar actuar durante 10 a 15 minutos, previo cepillado y\nfinalmente enjuagar.\n• Control de dermatofitosis (tiñas) o piodermias bacterianas: Mojar el animal a tratar, aplicar el\nproducto en su concentración original de acuerdo al tamaño del mismo, cepillar y permitir la\nformación de espuma. Dejar actuar durante 10-20 minutos y enjuagar.\nPresentaciones: Frasco conteniendo 250 ml. Botella conteniendo 1 litro. Bidón 5 litros.\nUso: Bovinos, Equinos, Ovinos, Porcinos, Caninos y Felinos.",
