        "texto": "Acción: Feline Fullspot, endectocida de aplicación spot-on. Su efectiva formulación elimina las\npulgas y los parásitos internos que frecuentemente afectan a los gatos. Para el tratamiento,\ncontrol y prevención de las parasitosis externas causadas por pulgas e internas causadas por\nnematodes y/o cestodes. Ejerce un rápido efecto letal sobre los parásitos intestinales y, al mismo\ntiempo, elimina a las pulgas, hospedadores intermediarios donde cumplen parte de su ciclo de vida\nparásitos internos como el Dipylidium caninum.\nFórmula: Cada 100 ml contiene: Imidacloprid 11,0 g, Ivermectina 0,2 g, Praziquantel 7,5 g,\nExcipientes c.s.p. 100 ml.\nDosificación: Una única dosis es terapéutica. El intervalo entre aplicaciones es de 30 días,\nfrecuencia que puede variar según el ambiente que habita el paciente, la parasitosis que desea\ncontrolar y/o la indicación del Médico Veterinario. Se recomienda a partir de las 12 semanas de vida\ny 1kg de peso. Puede utilizarse en animales enfermos y debilitados. Cada 30 días.\nPresentaciones: Estuche con pipeta acorde al peso del gato. Uso externo.\nGatos de 1kg a 2 kg, 2,1kg a 5kg y de más 5kg.\nUso: Gatos.",
